from lib import *
S = SS('g31')
steps = [
    step("同一个模块(各种后缀与 //go:build 的文件),go list 在不同环境下选中不同的文件。darwin/arm64:选中 cpu_arm64.go、family_unix.go、feat_release.go、main.go、os_darwin.go、windows.go;linux/amd64:选中 cpu_amd64.go、family_unix.go、feat_release.go、main.go、old_style.go、os_linux.go、windows.go;linux/arm64 加 -tags debug:feat_debug.go 取代 feat_release.go;windows/amd64:os_windows.go、family_win.go;linux/386:cpu_other.go(!amd64 && !arm64)。tool.go(//go:build ignore)在任何环境都被排除;windows.go(名字里没有下划线)在所有平台都选中;只写 // +build linux 的 old_style.go 仍然生效,只在 linux 选中。", t=tl(S(1)), done=lidx(S(1), 'GOOS=darwin GOARCH=arm64', 'GOOS=linux GOARCH=amd64:'), mark=lidx(S(1), '-tags debug', 'GOOS=windows', 'GOOS=linux GOARCH=386'), kv=KV([['文件名后缀 _GOOS / _GOARCH', '自动按平台选择(os_linux.go、cpu_arm64.go)'], ['//go:build !amd64 && !arm64', 'linux/386 选中 cpu_other.go'], ['-tags debug', 'feat_debug.go 取代 feat_release.go'], ['//go:build ignore', '所有平台都排除'], ['名字里没有下划线的 windows.go', '不受约束,所有平台都选中'], ['只有 // +build linux', '仍然生效']], ['名字里没有下划线的 windows.go'])),
    step("本机(darwin/arm64)实际运行:go run . 输出 “文件名后缀 _darwin | 文件名后缀 _arm64 | 正式版本 | unix 家族”;go run -tags debug . 把第三项换成 “debug 版本”;go run tool.go(显式给出文件)得到 “go run tool.go 才会用到”——显式指定文件时 //go:build ignore 不再生效。", t=tl(S(2)), done=lidx(S(2), 'go run .:', 'go run -tags debug'), mark=lidx(S(2), 'go run tool.go'), kv=KV([['go run .', '_darwin | _arm64 | 正式版本 | unix 家族'], ['go run -tags debug .', '第三项变成 debug 版本'], ['go run tool.go', '显式给出的文件不受 ignore 约束']], ['go run tool.go'])),
    step("tag 全集:context.ReleaseTags 有 27 个,最早 go1.1,最近 go1.24、go1.25、go1.26、go1.27(//go:build go1.21 这类版本约束靠它);ToolTags 里有 goexperiment.* 与 arm64.v8.0;CgoEnabled 在 CGO_ENABLED=0 时为 false,为 1 时为 true。unix 标签的满足情况:darwin、linux、freebsd、netbsd、openbsd、solaris、aix、android 满足;windows、js/wasm、plan9 不满足;ios/arm64 在没开 cgo 时 go list 就报错(requires external (cgo) linking, but cgo is not enabled)。", t=tl(S(3)), done=lidx(S(3), 'ReleaseTags', 'BuildTags'), mark=lidx(S(3), 'CGO_ENABLED=1', 'unix 标签'), kv=KV([['ReleaseTags', 'go1.1 … go1.27 共 27 个'], ['ToolTags', 'goexperiment.*、arm64.v8.0'], ['unix', 'darwin、linux、BSD 系、solaris、aix、android 满足;windows、js、plan9 不满足'], ['ios/arm64', '没开 cgo 时报错']], ['unix'])),
    step("go vet 检查构建约束:a.go 里 //go:build linux 写在 package 子句之后:misplaced //go:build comment(该约束被忽略,所以 darwin 上 a.go 仍被选中);b.go 同时写 //go:build linux 与 // +build darwin:+build lines do not match //go:build condition;c.go 只有 // +build linux:在 darwin 上被排除。go list 在本机的结果:选中 [a.go],排除 [b.go c.go]。", t=tl(S(4)), mark=lidx(S(4), 'misplaced //go:build', '+build lines do not match', '选中 | 排除'), kv=KV([['约束写在 package 之后', 'vet:misplaced //go:build comment;约束被忽略'], ['//go:build 与 // +build 不一致', 'vet:+build lines do not match //go:build condition'], ['go list 本机', '选中 [a.go];排除 [b.go c.go]']], ['约束写在 package 之后'])),
]
A = mkartg('g31', 31, 'Go,构建标签,go:build,条件编译,GOOS,真实验证,动画演示',
    '用 go list 在不同 GOOS / GOARCH / -tags 下验证 Go 1.27.1 的构建约束:_GOOS、_GOARCH 文件名后缀与 //go:build 表达式共同决定哪些文件参与编译;名字里没有下划线的 windows.go 不受约束;//go:build ignore 的文件只在 go run 显式给出时才被使用;旧的 // +build 仍然生效;unix 标签覆盖哪些系统;go vet 能发现写错位置和两种写法不一致。',
    '条件编译在 Go 里靠“文件级”的约束完成:文件名后缀与文件顶部的 //go:build。这篇不靠记忆,用 go list 与 go run 在不同平台与标签下看哪些文件被选中,再列出 tag 全集,最后看 go vet 能帮你抓住哪些书写错误。',
    [('27 个', 'context.ReleaseTags 里的发布标签数(go1.1 到 go1.27)'), ('unix', '满足的系统:darwin、linux、BSD 系、solaris、aix、android;不满足:windows、js、plan9'), ('misplaced', '//go:build 写在 package 子句之后会被 go vet 报告,并且不生效')],
    [('文件选择规则', '<p>一个文件参与编译,要同时满足:文件名后缀(<code>_linux</code>、<code>_arm64</code>、<code>_linux_arm64</code>)与顶部的 <code>//go:build</code> 表达式。名字里没有下划线的 <code>windows.go</code> 不算后缀,所以到处都选中;<code>_test.go</code> 只在测试时参与。上表可以直接当成检查清单:改一个文件名或约束之后,用 <code>go list -f \'{{.GoFiles}}\'</code> 在目标平台上看一遍。</p>'),
     ('go run 与 ignore', '<p><code>//go:build ignore</code> 是写“只供 go run 的小工具”的惯用法:按包构建时它不参与,显式 <code>go run tool.go</code> 时命令行给出的文件直接使用,不再检查约束。</p>'),
     ('tag 全集', '<p>满足 <code>//go:build go1.21</code> 这样的版本约束靠 <code>ReleaseTags</code>;<code>unix</code> 是一个汇总标签(<code>go help buildconstraint</code> 写的是 “if GOOS is a Unix or Unix-like system”),省得枚举所有类 unix 系统。上面的清单是在本机逐个 GOOS 用 go list 实测的;<code>ToolTags</code> 里出现的几个 <code>goexperiment.*</code>(如 jsonv2、greenteagc)说明这个工具链默认开了这些实验特性,具体含义本文没有展开。</p>'),
     ('go vet 能帮什么', '<p>最常见的两个错误:把 <code>//go:build</code> 写到 <code>package</code> 之后(不生效,还没有编译错误,只有 vet 会告诉你),以及新旧两种写法互相矛盾。<code>gofmt</code> 会自动让两者保持一致;建议新代码只写 <code>//go:build</code>。</p>')],
    steps,
    [ENV_G + '。选中的文件来自 go list -f 在不同 GOOS/GOARCH/-tags 下的真实输出(CGO_ENABLED=0,交叉平台只列文件,没有真的编译运行);实际运行只在本机 darwin/arm64 上做',
     '没有验证:cgo 标签与带 cgo 文件的约束、GOARM / GOAMD64 级别标签(如 amd64.v3)、go:build 里括号与优先级的完整规则(只用了 && 与 !)、构建标签与 go.mod 里 go 版本的交互、-tags 里逗号与空格分隔的历史差异'],
    '构建标签与条件编译')
